/*
 * Standalone executable semantics harness for the two vdso_addr algorithms.
 *
 * This is NOT a kernel build. It re-implements, verbatim, the arithmetic of:
 *   old = target arch/x86/vdso/vma.c:vdso_addr before the fix
 *   new = candidate arch/x86/vdso/vma.c:vdso_addr after the fix
 * with the x86_64 constants used by the target (PAGE_SHIFT=12, PMD_SHIFT=21,
 * PTRS_PER_PTE=512, TASK_SIZE_MAX=(1<<47)-PAGE_SIZE). The final align_addr()
 * call is omitted because it only adjusts for the AMD F15h I$ aliasing quirk
 * and is identical in both versions.
 *
 * It checks the security invariants claimed by the fix:
 *  I1 the selected address is page aligned;
 *  I2 the selected address is not below the (page-aligned) randomized start;
 *  I3 the selected mapping fits below TASK_SIZE_MAX (addr + len <= TASK_SIZE_MAX);
 *  I4 the address is chosen uniformly over the usable page range (not clustered
 *     and not collapsed to a single value when the range is awkward).
 */
#include <stdio.h>
#include <stdint.h>

#define PAGE_SHIFT 12
#define PAGE_SIZE (1UL << PAGE_SHIFT)
#define PAGE_MASK (~(PAGE_SIZE - 1))
#define PAGE_ALIGN(x) (((x) + PAGE_SIZE - 1) & PAGE_MASK)
#define PMD_SIZE (1UL << 21)
#define PMD_MASK (~(PMD_SIZE - 1))
#define TASK_SIZE_MAX 0x00007ffffffff000UL
#define PTRS_PER_PTE 512

static unsigned long old_vdso_addr(unsigned long start, unsigned len,
				   unsigned rnd)
{
	unsigned long addr, end;
	unsigned offset;
	end = (start + PMD_SIZE - 1) & PMD_MASK;
	if (end >= TASK_SIZE_MAX)
		end = TASK_SIZE_MAX;
	end -= len;
	offset = rnd & (PTRS_PER_PTE - 1);
	addr = start + ((unsigned long)offset << PAGE_SHIFT);
	if (addr >= end)
		addr = end;
	addr = PAGE_ALIGN(addr);
	return addr;
}

static unsigned long new_vdso_addr(unsigned long start, unsigned len,
				   unsigned rnd)
{
	unsigned long addr, end;
	unsigned offset;

	start = PAGE_ALIGN(start);
	end = (start + len + PMD_SIZE - 1) & PMD_MASK;
	if (end >= TASK_SIZE_MAX)
		end = TASK_SIZE_MAX;
	end -= len;

	if (end > start) {
		offset = rnd % (((end - start) >> PAGE_SHIFT) + 1);
		addr = start + ((unsigned long)offset << PAGE_SHIFT);
	} else {
		addr = start;
	}
	return addr;
}

static unsigned long new_end(unsigned long start, unsigned len)
{
	unsigned long end;
	start = PAGE_ALIGN(start);
	end = (start + len + PMD_SIZE - 1) & PMD_MASK;
	if (end >= TASK_SIZE_MAX)
		end = TASK_SIZE_MAX;
	return end - len;
}

static int failures;
#define CHECK(cond, fmt, ...) do { \
	if (!(cond)) { failures++; printf("FAIL: " fmt "\n", ##__VA_ARGS__); } \
} while (0)

int main(void)
{
	const unsigned len = 0x2000;	/* two-page vdso image, target-like */
	unsigned long start;
	unsigned int rnd;
	int i;

	printf("== per-start invariant scan (len=0x%x) ==\n", len);
	for (i = 0; i < 4096; i++) {
		unsigned long base = TASK_SIZE_MAX - 0x20000000UL -
				    (unsigned long)(i * 33) * 0x1000;
		unsigned long sa;
		unsigned long e;

		for (sa = base + (i & 0xfff); sa < base + 0x3000; sa += 0x37) {
			unsigned long n_addr, o_addr;

			/* rnd values chosen across the whole 32-bit domain */
			rnd = (unsigned)(i * 2654435761u);
			n_addr = new_vdso_addr(sa, len, rnd);
			o_addr = old_vdso_addr(sa, len, rnd);
			e = new_end(sa, len);

			CHECK((n_addr & (PAGE_SIZE - 1)) == 0,
			      "new addr %lx not page aligned (start=%lx rnd=%u)",
			      n_addr, sa, rnd);
			CHECK(n_addr >= PAGE_ALIGN(sa),
			      "new addr %lx below PAGE_ALIGN(start)=%lx",
			      n_addr, PAGE_ALIGN(sa));
			CHECK(n_addr <= e,
			      "new addr %lx above end %lx (start=%lx)",
			      n_addr, e, sa);
			CHECK(n_addr + len <= TASK_SIZE_MAX,
			      "new addr %lx + len exceeds TASK_SIZE_MAX",
			      n_addr);

			/* record the old defect without aborting */
			if (rnd == 0 && (o_addr < PAGE_ALIGN(sa))) {
				printf("observed old defect: start=%lx rnd=0 old=%lx < PAGE_ALIGN(start)=%lx\n",
				       sa, o_addr, PAGE_ALIGN(sa));
			}
			if (o_addr + len > TASK_SIZE_MAX) {
				printf("observed old overflow: start=%lx rnd=0 old=%lx\n",
				       sa, o_addr);
			}
		}
	}

	printf("\n== entropy for an awkward start near the end of a PMD ==\n");
	start = 0x00007fffff1ff123UL;	/* unaligned, PMD offset near 2MB */
	{
		unsigned long seen_new[600], seen_old[600];
		int nn = 0, no = 0, j, k, found;

		for (rnd = 0; rnd < 2000000u; rnd++) {
			unsigned long a = new_vdso_addr(start, len, rnd);
			unsigned long b = old_vdso_addr(start, len, rnd);
			found = 0;
			for (j = 0; j < nn; j++) if (seen_new[j] == a) { found = 1; break; }
			if (!found && nn < 600) seen_new[nn++] = a;
			found = 0;
			for (j = 0; j < no; j++) if (seen_old[j] == b) { found = 1; break; }
			if (!found && no < 600) seen_old[no++] = b;
			(void)k;
		}
		printf("start=%lx range_pages=%lu distinct_new=%d distinct_old=%d\n",
		       start, ((new_end(start, len) - PAGE_ALIGN(start)) >> PAGE_SHIFT) + 1,
		       nn, no);
		CHECK(nn > no, "new algorithm did not increase entropy (%d vs %d)",
		      nn, no);
	}

	printf("\n== empty-range fallback (I4 edge case) ==\n");
	{
		/* start forced so PAGE_ALIGN(start) >= end -> must return start */
		unsigned long s = TASK_SIZE_MAX - 1;
		unsigned long a = new_vdso_addr(s, len, 12345u);
		CHECK((a & (PAGE_SIZE - 1)) == 0, "fallback not aligned: %lx", a);
		CHECK(a <= new_end(s, len) || new_end(s, len) <= PAGE_ALIGN(s),
		      "fallback out of range");
	}

	if (failures) {
		printf("\nRESULT: %d invariant failure(s)\n", failures);
		return 1;
	}
	printf("\nRESULT: all invariants hold\n");
	return 0;
}

